CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle. Unique, short, and case-insensitively compared so @Ada and @ada are the same person.
	"username" VARCHAR(30) NOT NULL UNIQUE,
	-- Login identity, never shown publicly.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Argon2id hash. Null for accounts that only use a social login.
	"password_hash" VARCHAR(255),
	-- Name shown beside the handle. Free-form and changeable.
	"display_name" VARCHAR(80),
	-- Profile description.
	"bio" VARCHAR(300),
	-- Profile image URL in object storage.
	"avatar_url" VARCHAR(500),
	-- Private accounts require follow requests to be approved before content is visible.
	"is_private" BOOLEAN NOT NULL DEFAULT false,
	-- Identity verification badge.
	"is_verified" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised counter. Maintained asynchronously because counting followers of a popular account on every profile view does not scale.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised counter of accounts this user follows.
	"following_count" INTEGER NOT NULL DEFAULT 0,
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft deactivation. Content stays addressable while the account is recoverable.
	"deactivated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'An account. Counters live here rather than being computed, because a profile page is read far more often than a follow is created.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."username" IS 'Public handle. Unique, short, and case-insensitively compared so @Ada and @ada are the same person.';
COMMENT ON COLUMN "users"."email" IS 'Login identity, never shown publicly.';
COMMENT ON COLUMN "users"."password_hash" IS 'Argon2id hash. Null for accounts that only use a social login.';
COMMENT ON COLUMN "users"."display_name" IS 'Name shown beside the handle. Free-form and changeable.';
COMMENT ON COLUMN "users"."bio" IS 'Profile description.';
COMMENT ON COLUMN "users"."avatar_url" IS 'Profile image URL in object storage.';
COMMENT ON COLUMN "users"."is_private" IS 'Private accounts require follow requests to be approved before content is visible.';
COMMENT ON COLUMN "users"."is_verified" IS 'Identity verification badge.';
COMMENT ON COLUMN "users"."follower_count" IS 'Denormalised counter. Maintained asynchronously because counting followers of a popular account on every profile view does not scale.';
COMMENT ON COLUMN "users"."following_count" IS 'Denormalised counter of accounts this user follows.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';
COMMENT ON COLUMN "users"."deactivated_at" IS 'Soft deactivation. Content stays addressable while the account is recoverable.';

CREATE TABLE IF NOT EXISTS "follows" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The account doing the following.
	"follower_id" BIGINT NOT NULL,
	-- The account being followed.
	"followee_id" BIGINT NOT NULL,
	-- accepted | pending. Pending exists only for private accounts, where a follow is a request.
	"status" VARCHAR(16) NOT NULL DEFAULT 'accepted',
	-- When the follow or request was created.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "follows" IS 'Asymmetric relationship: A following B says nothing about B following A. The unique pair prevents duplicates, and the reverse index is what makes "who follows me" as cheap as "who do I follow".';
COMMENT ON COLUMN "follows"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "follows"."follower_id" IS 'The account doing the following.';
COMMENT ON COLUMN "follows"."followee_id" IS 'The account being followed.';
COMMENT ON COLUMN "follows"."status" IS 'accepted | pending. Pending exists only for private accounts, where a follow is a request.';
COMMENT ON COLUMN "follows"."created_at" IS 'When the follow or request was created.';

CREATE UNIQUE INDEX "uq_follows_follower_followee"
ON "follows" ("follower_id", "followee_id");
CREATE INDEX "idx_follows_followee_status"
ON "follows" ("followee_id", "status");

CREATE TABLE IF NOT EXISTS "blocks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that created the block.
	"blocker_id" BIGINT NOT NULL,
	-- Account being blocked.
	"blocked_id" BIGINT NOT NULL,
	-- When the block was created.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "blocks" IS 'Blocks are checked on every feed and profile read, so they are a small dedicated table indexed in both directions rather than a flag buried on the follow row.';
COMMENT ON COLUMN "blocks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "blocks"."blocker_id" IS 'Account that created the block.';
COMMENT ON COLUMN "blocks"."blocked_id" IS 'Account being blocked.';
COMMENT ON COLUMN "blocks"."created_at" IS 'When the block was created.';

CREATE UNIQUE INDEX "uq_blocks_blocker_blocked"
ON "blocks" ("blocker_id", "blocked_id");
CREATE INDEX "idx_blocks_blocked"
ON "blocks" ("blocked_id");

CREATE TABLE IF NOT EXISTS "posts" (
	-- Surrogate primary key. Time-sortable ids (ULID or Snowflake) are the usual upgrade here.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that posted.
	"author_id" BIGINT NOT NULL,
	-- Post being replied to, for a threaded reply.
	"parent_post_id" BIGINT,
	-- Original post when this is a repost. A repost with no body is a pure share; with a body it is a quote.
	"repost_of_id" BIGINT,
	-- Post text. Null when the post is media only.
	"body" VARCHAR(1000),
	-- public | followers | mentioned. Evaluated on every read alongside blocks.
	"visibility" VARCHAR(16) NOT NULL DEFAULT 'public',
	-- Denormalised counter updated asynchronously.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised reply counter.
	"reply_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised repost counter.
	"repost_count" INTEGER NOT NULL DEFAULT 0,
	-- Post time. The feed sorts on this, so it is the leading column of the feed index.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft deletion, so replies and quotes do not lose their anchor.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "posts" IS 'One table for posts, replies and reposts, distinguished by which reference is set. Separate tables for each would triple the feed query for no gain.';
COMMENT ON COLUMN "posts"."id" IS 'Surrogate primary key. Time-sortable ids (ULID or Snowflake) are the usual upgrade here.';
COMMENT ON COLUMN "posts"."author_id" IS 'Account that posted.';
COMMENT ON COLUMN "posts"."parent_post_id" IS 'Post being replied to, for a threaded reply.';
COMMENT ON COLUMN "posts"."repost_of_id" IS 'Original post when this is a repost. A repost with no body is a pure share; with a body it is a quote.';
COMMENT ON COLUMN "posts"."body" IS 'Post text. Null when the post is media only.';
COMMENT ON COLUMN "posts"."visibility" IS 'public | followers | mentioned. Evaluated on every read alongside blocks.';
COMMENT ON COLUMN "posts"."like_count" IS 'Denormalised counter updated asynchronously.';
COMMENT ON COLUMN "posts"."reply_count" IS 'Denormalised reply counter.';
COMMENT ON COLUMN "posts"."repost_count" IS 'Denormalised repost counter.';
COMMENT ON COLUMN "posts"."created_at" IS 'Post time. The feed sorts on this, so it is the leading column of the feed index.';
COMMENT ON COLUMN "posts"."deleted_at" IS 'Soft deletion, so replies and quotes do not lose their anchor.';

CREATE INDEX "idx_posts_author_created"
ON "posts" ("author_id", "created_at");
CREATE INDEX "idx_posts_parent_created"
ON "posts" ("parent_post_id", "created_at");
CREATE INDEX "idx_posts_created"
ON "posts" ("created_at");

CREATE TABLE IF NOT EXISTS "post_media" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Post the attachment belongs to.
	"post_id" BIGINT NOT NULL,
	-- Object storage key for the file.
	"storage_key" VARCHAR(500) NOT NULL,
	-- image | video | gif.
	"media_type" VARCHAR(16) NOT NULL,
	-- Pixel width, so the client can reserve space before the file loads.
	"width" INTEGER,
	-- Pixel height.
	"height" INTEGER,
	-- Length for video.
	"duration_seconds" INTEGER,
	-- Alternative text for screen readers.
	"alt_text" VARCHAR(300),
	-- Order within the post, for multi-image posts.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "post_media" IS 'Attachments as rows rather than an array column, so ordering, per-file alt text and dimensions each have a home.';
COMMENT ON COLUMN "post_media"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "post_media"."post_id" IS 'Post the attachment belongs to.';
COMMENT ON COLUMN "post_media"."storage_key" IS 'Object storage key for the file.';
COMMENT ON COLUMN "post_media"."media_type" IS 'image | video | gif.';
COMMENT ON COLUMN "post_media"."width" IS 'Pixel width, so the client can reserve space before the file loads.';
COMMENT ON COLUMN "post_media"."height" IS 'Pixel height.';
COMMENT ON COLUMN "post_media"."duration_seconds" IS 'Length for video.';
COMMENT ON COLUMN "post_media"."alt_text" IS 'Alternative text for screen readers.';
COMMENT ON COLUMN "post_media"."position" IS 'Order within the post, for multi-image posts.';

CREATE INDEX "idx_post_media_post_position"
ON "post_media" ("post_id", "position");

CREATE TABLE IF NOT EXISTS "likes" (
	-- Account that liked. Half of the composite primary key.
	"user_id" BIGINT,
	-- Post liked. The other half — the pair is the key, so liking twice is impossible.
	"post_id" BIGINT,
	-- When the like happened.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id", "post_id")
);

COMMENT ON TABLE "likes" IS 'The highest-write table in the system. A composite primary key with no surrogate id keeps it as narrow as possible and makes the unlike path a single delete by key.';
COMMENT ON COLUMN "likes"."user_id" IS 'Account that liked. Half of the composite primary key.';
COMMENT ON COLUMN "likes"."post_id" IS 'Post liked. The other half — the pair is the key, so liking twice is impossible.';
COMMENT ON COLUMN "likes"."created_at" IS 'When the like happened.';

CREATE INDEX "idx_likes_post_created"
ON "likes" ("post_id", "created_at");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Post being commented on.
	"post_id" BIGINT NOT NULL,
	-- Comment author.
	"author_id" BIGINT NOT NULL,
	-- Comment being replied to. Null at the top level.
	"parent_comment_id" BIGINT,
	-- Comment text.
	"body" VARCHAR(1000) NOT NULL,
	-- Denormalised like counter.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Submission time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft deletion, so replies keep their parent.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'Comments are kept separate from posts here because they are not feed items: they are never reposted, never appear standalone, and are always read in the context of one post.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."post_id" IS 'Post being commented on.';
COMMENT ON COLUMN "comments"."author_id" IS 'Comment author.';
COMMENT ON COLUMN "comments"."parent_comment_id" IS 'Comment being replied to. Null at the top level.';
COMMENT ON COLUMN "comments"."body" IS 'Comment text.';
COMMENT ON COLUMN "comments"."like_count" IS 'Denormalised like counter.';
COMMENT ON COLUMN "comments"."created_at" IS 'Submission time.';
COMMENT ON COLUMN "comments"."deleted_at" IS 'Soft deletion, so replies keep their parent.';

CREATE INDEX "idx_comments_post_created"
ON "comments" ("post_id", "created_at");
CREATE INDEX "idx_comments_parent"
ON "comments" ("parent_comment_id");

CREATE TABLE IF NOT EXISTS "conversations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- False for a one-to-one thread, true for a group.
	"is_group" BOOLEAN NOT NULL DEFAULT false,
	-- Group name. Null for direct threads, which are titled from the participants.
	"title" VARCHAR(120),
	-- Account that started the conversation.
	"created_by_id" BIGINT,
	-- Timestamp of the newest message, denormalised so the inbox sorts without touching the messages table.
	"last_message_at" TIMESTAMP,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "conversations" IS 'A message thread. Modelling one-to-one and group chats as the same entity avoids a second code path the day group chat ships.';
COMMENT ON COLUMN "conversations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "conversations"."is_group" IS 'False for a one-to-one thread, true for a group.';
COMMENT ON COLUMN "conversations"."title" IS 'Group name. Null for direct threads, which are titled from the participants.';
COMMENT ON COLUMN "conversations"."created_by_id" IS 'Account that started the conversation.';
COMMENT ON COLUMN "conversations"."last_message_at" IS 'Timestamp of the newest message, denormalised so the inbox sorts without touching the messages table.';
COMMENT ON COLUMN "conversations"."created_at" IS 'Creation time.';

CREATE INDEX "idx_conversations_last_message"
ON "conversations" ("last_message_at");

CREATE TABLE IF NOT EXISTS "conversation_participants" (
	-- Thread joined. Half of the composite primary key.
	"conversation_id" BIGINT,
	-- Participant. The other half of the key.
	"user_id" BIGINT,
	-- When the participant joined.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Newest message this participant has read. Unread counts are derived from it instead of a per-message read flag.
	"last_read_message_id" BIGINT,
	-- Suppresses notifications without leaving the thread.
	"muted" BOOLEAN NOT NULL DEFAULT false,
	-- When the participant left. Kept so their historical messages still resolve.
	"left_at" TIMESTAMP,
	PRIMARY KEY("conversation_id", "user_id")
);

COMMENT ON TABLE "conversation_participants" IS 'Membership of a thread. The read pointer is per participant, which is how unread counts stay O(1) to maintain in a group chat.';
COMMENT ON COLUMN "conversation_participants"."conversation_id" IS 'Thread joined. Half of the composite primary key.';
COMMENT ON COLUMN "conversation_participants"."user_id" IS 'Participant. The other half of the key.';
COMMENT ON COLUMN "conversation_participants"."joined_at" IS 'When the participant joined.';
COMMENT ON COLUMN "conversation_participants"."last_read_message_id" IS 'Newest message this participant has read. Unread counts are derived from it instead of a per-message read flag.';
COMMENT ON COLUMN "conversation_participants"."muted" IS 'Suppresses notifications without leaving the thread.';
COMMENT ON COLUMN "conversation_participants"."left_at" IS 'When the participant left. Kept so their historical messages still resolve.';

CREATE INDEX "idx_participants_user"
ON "conversation_participants" ("user_id");

CREATE TABLE IF NOT EXISTS "messages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Thread the message belongs to.
	"conversation_id" BIGINT NOT NULL,
	-- Account that sent it.
	"sender_id" BIGINT NOT NULL,
	-- Message text. Null for a media-only message.
	"body" VARCHAR(4000),
	-- Object storage key for an attachment.
	"media_key" VARCHAR(500),
	-- Send time. The thread view pages backwards on this.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit time, shown in the UI as edited.
	"edited_at" TIMESTAMP,
	-- Soft deletion, so a tombstone can be shown in place.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "messages" IS 'Messages are append-only in practice and always read by conversation and time, which is exactly what the single composite index serves.';
COMMENT ON COLUMN "messages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "messages"."conversation_id" IS 'Thread the message belongs to.';
COMMENT ON COLUMN "messages"."sender_id" IS 'Account that sent it.';
COMMENT ON COLUMN "messages"."body" IS 'Message text. Null for a media-only message.';
COMMENT ON COLUMN "messages"."media_key" IS 'Object storage key for an attachment.';
COMMENT ON COLUMN "messages"."created_at" IS 'Send time. The thread view pages backwards on this.';
COMMENT ON COLUMN "messages"."edited_at" IS 'Last edit time, shown in the UI as edited.';
COMMENT ON COLUMN "messages"."deleted_at" IS 'Soft deletion, so a tombstone can be shown in place.';

CREATE INDEX "idx_messages_conversation_created"
ON "messages" ("conversation_id", "created_at");

CREATE TABLE IF NOT EXISTS "notifications" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account being notified.
	"recipient_id" BIGINT NOT NULL,
	-- Account whose action caused it. Null for system notifications.
	"actor_id" BIGINT,
	-- follow | like | comment | mention | repost | message.
	"notification_type" VARCHAR(32) NOT NULL,
	-- Entity class the notification points at, e.g. post or comment.
	"target_type" VARCHAR(24),
	-- Identifier of that entity, kept loose so one table serves every type.
	"target_id" BIGINT,
	-- Read state. The partial index on unread rows is what makes the badge count cheap.
	"is_read" BOOLEAN NOT NULL DEFAULT false,
	-- Event time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "notifications" IS 'One row per notifiable event. High-volume accounts need these collapsed ("Ada and 1,200 others liked your post"), which is a read-time grouping over this table rather than a different write path.';
COMMENT ON COLUMN "notifications"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "notifications"."recipient_id" IS 'Account being notified.';
COMMENT ON COLUMN "notifications"."actor_id" IS 'Account whose action caused it. Null for system notifications.';
COMMENT ON COLUMN "notifications"."notification_type" IS 'follow | like | comment | mention | repost | message.';
COMMENT ON COLUMN "notifications"."target_type" IS 'Entity class the notification points at, e.g. post or comment.';
COMMENT ON COLUMN "notifications"."target_id" IS 'Identifier of that entity, kept loose so one table serves every type.';
COMMENT ON COLUMN "notifications"."is_read" IS 'Read state. The partial index on unread rows is what makes the badge count cheap.';
COMMENT ON COLUMN "notifications"."created_at" IS 'Event time.';

CREATE INDEX "idx_notifications_recipient_unread"
ON "notifications" ("recipient_id", "is_read", "created_at");

